import java.nio.file.*;import java.util.*;import java.util.zip.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class Patch implements Opcodes {
 public static void main(String[] a)throws Exception{String mode=a[0],helper="dev/zomboid/"+mode+"/fast/FastReflection";Set<String> targets=mode.equals("hordes")?Set.of("dev/zomboid/reactive/R.class","dev/zomboid/hordes/ChunkReflection.class"):Set.of("dev/zomboid/gore/R.class");Map<String,byte[]> data=new TreeMap<>();int hooks=0,methods=0;
 try(ZipFile z=new ZipFile(a[1])){for(var es=z.entries();es.hasMoreElements();){var e=es.nextElement();byte[] b=z.getInputStream(e).readAllBytes();if(targets.contains(e.getName())){ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);for(MethodNode m:c.methods)if(Set.of("type","call","get","set","make","create").contains(m.name)&&(m.access&ACC_STATIC)!=0){m.instructions.clear();m.tryCatchBlocks.clear();m.localVariables=null;Type[] args=Type.getArgumentTypes(m.desc);int slot=0;for(Type t:args){m.instructions.add(new VarInsnNode(t.getOpcode(ILOAD),slot));slot+=t.getSize();}m.instructions.add(new MethodInsnNode(INVOKESTATIC,helper,m.name.equals("create")?"make":m.name,m.desc,false));m.instructions.add(new InsnNode(Type.getReturnType(m.desc).getOpcode(IRETURN)));m.maxLocals=slot;hooks++;}ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);b=w.toByteArray();}if(mode.equals("gore")&&e.getName().equals("dev/zomboid/gore/Events.class")){ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);MethodNode m=new MethodNode(ACC_PUBLIC|ACC_STATIC,"collectNearbyDrops","(Lnet/neoforged/neoforge/event/tick/LevelTickEvent$Post;)V",null,null);m.visitAnnotation("Lnet/neoforged/bus/api/SubscribeEvent;",true).visitEnd();m.instructions.add(new VarInsnNode(ALOAD,0));m.instructions.add(new MethodInsnNode(INVOKESTATIC,"dev/zomboid/gore/CorpseCollect","tick","(Ljava/lang/Object;)V",false));m.instructions.add(new InsnNode(RETURN));m.maxLocals=1;m.maxStack=1;c.methods.add(m);ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);b=w.toByteArray();}data.put(e.getName(),b);}}
 if(hooks!=(mode.equals("hordes")?10:5))throw new IllegalStateException("Wrong hooks "+hooks);
 try(var f=Files.walk(Path.of(a[3]))){for(var p:f.filter(p->p.toString().endsWith(".class")).toList()){String n=Path.of(a[3]).relativize(p).toString();if(n.contains("/"+mode+"/"))data.put(n,Files.readAllBytes(p));}}
 for(var e:data.entrySet())if(e.getKey().endsWith(".class")){ClassNode c=new ClassNode();new ClassReader(e.getValue()).accept(c,0);for(var m:c.methods)if((m.access&(ACC_ABSTRACT|ACC_NATIVE))==0){new Analyzer<BasicValue>(new BasicVerifier()).analyze(c.name,m);methods++;}}
 try(var z=new ZipOutputStream(Files.newOutputStream(Path.of(a[2])))){for(var e:data.entrySet()){z.putNextEntry(new ZipEntry(e.getKey()));z.write(e.getValue());z.closeEntry();}}
 System.out.println(mode+": reflection hooks "+hooks+", verified methods "+methods);
 }
}
